from pathlib import Path
import re,sys
p=Path(sys.argv[1]);s=p.read_text(encoding='utf-8',errors='replace')
def rm(tag,id):
 global s;s=re.sub(rf'<{tag}\b[^>]*id=["\']{re.escape(id)}["\'][^>]*>.*?</{tag}>\s*','',s,flags=re.S|re.I)
def bal(id):
 m=re.search(rf'<div\b[^>]*id=["\']{re.escape(id)}["\'][^>]*>',s,re.I)
 if not m:return None
 d=0
 for x in re.finditer(r'</?div\b[^>]*>',s[m.start():],re.I):
  t=x.group();d+=-1 if t.startswith('</') else 1
  if d==0:return m.start(),m.end(),m.start()+x.start(),m.start()+x.end()
def rmdiv(id):
 global s
 q=bal(id)
 if q:s=s[:q[0]]+s[q[3]:]
for x in ['ayb_v28_same_program_mobile_css','ayb_v16_68_professional_ui_css']:rm('style',x)
for x in ['ayb_v28_same_program_mobile_js','ayb_v16_68_professional_ui_js','ayb_section_tabs_toolbar_v21_js']:rm('script',x)
s=re.sub(r'<input\b[^>]*id=["\']aybV28ImportInput["\'][^>]*>\s*','',s,flags=re.I)
for x in ['aybV28MobileDock','aybV28ExportSheet']:rmdiv(x)
