s=re.sub(r'<title>.*?</title>','<title>BY EDŞ SAHA</title>',s,count=1,flags=re.S|re.I)
s=re.sub(r'<div class="titlebar">.*?</div>\s*<style>', '<div class="titlebar"><img src="icons/icon-192.png" class="by-title-icon"><div class="title">BY EDŞ SAHA</div><span id="activeProjectName" style="display:none">Proje yok</span><div class="win-controls"><span id="aybWinMin">—</span><span id="aybWinMax">□</span><span id="aybWinClose">×</span></div></div><style>',s,count=1,flags=re.S)
