s=s.replace('</head>',css+'</head>',1)
js=r'''<script id="ayb_v57_final_js">(function(){const d=document,$=(x,r=d)=>r.querySelector(x),$$=(x,r=d)=>Array.from(r.querySelectorAll(x)),secs=['project','draw','edit','analysis','report','print','symbols','fielddata'];function gs(g){return secs.find(x=>g.classList.contains(x))||''}function sec(x,sv){if(!secs.includes(x))x='draw';d.body.dataset.aybSection=x;$$('.ayb-ribbon-tab').forEach(b=>b.classList.toggle('active',b.dataset.section===x));$$('#aybRibbonTools>.ayb-pro-group').forEach(g=>g.classList.toggle('ayb-section-visible',gs(g)===x));if(sv)try{localStorage.setItem('ayb_v57_sec',x)}catch(e){}}function ord(){const r=$('#aybRibbonTools .ayb-pro-group.draw .ayb-pro-row');if(!r)return;['[data-tool="direk"]','[data-tool="trafo"]','[data-tool="yeraltihat"]','[data-tool="hat"]','[data-tool="abonehat"]','[data-tool="kanal"]','[data-tool="kofre"]','[data-tool="bina"]','[data-tool="box"]','[data-tool="sahanot"]','#aybYolOlcBtn','#kfMeasureToolBtn','[data-tool="cizgi"]','[data-tool="ok"]','#aybTopluSilBtn'].forEach(x=>{const e=$(x,r)||$(x);if(e&&e.parentElement===r)r.appendChild(e)});[['[data-tool="yeraltihat"]','Yeraltı Hat'],['[data-tool="hat"]','Havai Hat'],['[data-tool="abonehat"]','Abone'],['[data-tool="sahanot"]','NOT'],['#aybYolOlcBtn','Yol Ölç'],['#kfMeasureToolBtn','Ölç'],['#aybTopluSilBtn','Toplu Sil']].forEach(a=>{const e=$(a[0],r),t=e&&$('small',e);if(t)t.textContent=a[1]})}function boot(){const t=$('#aybRibbonTabs');if(t&&!t.__b){t.__b=1;t.onclick=e=>{const b=e.target.closest('[data-section]');if(b)sec(b.dataset.section,1)}};ord();let x='draw';try{x=localStorage.getItem('ayb_v57_sec')||'draw'}catch(e){}sec(x)}if(d.readyState==='loading')d.addEventListener('DOMContentLoaded',boot,{once:true});else boot();addEventListener('load',()=>[50,250,800,1800,3200].forEach(x=>setTimeout(()=>{boot();ord()},x)),{once:true});
const P=[['Lamba Arızalı','Lamba arızalıdır; kontrol ve değişim gereklidir.'],['Lambası Yanmıyor','Lamba yanmıyor; enerji ve armatür kontrolü gereklidir.'],['Direk Hasarlı','Direk hasarlıdır; saha kontrolü ve onarım/değişim gereklidir.'],['Otomat Kapağı Yok','Otomat kapağı yoktur; güvenlik için kapak takılmalıdır.'],['Otomat Kapağı Yok Kablolar Dışarda','Otomat kapağı yok ve kablolar dışarıdadır; acil güvenlik müdahalesi gereklidir.'],['Kablolar Dışarda','Kablolar dışarıdadır; izolasyon ve kapatma gereklidir.'],['Armatür Hasarlı','Armatür hasarlıdır; kontrol ve değişim gereklidir.'],['Hat / Kablo Hasarı','Hat veya kabloda hasar vardır.'],['Saha Engeli','Çalışmaya engel saha durumu bulunmaktadır.'],['Diğer','']];
const MM=window.__aybNoteMk instanceof Map?window.__aybNoteMk:new Map;window.__aybNoteMk=MM;function rem(id){const m=MM.get(String(id));if(m){try{map.removeLayer(m)}catch(e){}MM.delete(String(id));try{const i=otherLayers.indexOf(m);if(i>=0)otherLayers.splice(i,1)}catch(e){}}}function pop(n){return `<div data-nid="${aybSahaNotEsc(n.id)}"><b>📝 ${aybSahaNotEsc(n.tur)}</b><br>${n.objeNo?'<b>Obje:</b> '+aybSahaNotEsc(n.objeNo)+'<br>':''}${aybSahaNotEsc(n.aciklama||'').replace(/\n/g,'<br>')}${n.foto?'<img src="'+n.foto+'" style="display:block;max-width:300px;max-height:220px;margin:7px auto">':''}<div style="margin-top:7px"><button data-ne>Düzenle</button> <button data-nd style="color:#991b1b">Sil</button></div></div>`}window.renderSahaNot=function(n){if(!n||!map)return;let m=MM.get(String(n.id));if(m&&map.hasLayer(m)){m.setLatLng([+n.lat,+n.lng]);m.setPopupContent(pop(n));return m}const ic=L.divIcon({className:'ayb-saha-note-marker',html:aybSahaNotIconHtml(n.id),iconSize:[24,24],iconAnchor:[12,12]});m=L.marker([+n.lat,+n.lng],{icon:ic,zIndexOffset:1500,bubblingMouseEvents:false}).addTo(map);MM.set(String(n.id),m);otherLayers.push(m);m.bindPopup(pop(n));m.on('popupopen',e=>{const x=e.popup.getElement(),a=x&&x.querySelector('[data-ne]'),z=x&&x.querySelector('[data-nd]');if(a)a.onclick=()=>aybOpenSahaNotForm(L.latLng(n.lat,n.lng),n);if(z)z.onclick=()=>window.aybSahaNotSil(n.id)});m.on('contextmenu',e=>{L.DomEvent.stop(e);aybOpenSahaNotForm(L.latLng(n.lat,n.lng),n)});try{aybBindLongPress(m,()=>aybOpenSahaNotForm(L.latLng(n.lat,n.lng),n))}catch(e){}return m};window.aybSahaNotSil=function(id){if(!confirm('Bu saha notu silinsin mi?'))return false;project.sahaNotes=aybSahaNotes().filter(x=>String(x.id)!==String(id));projects[project.id]=project;rem(id);try{map.closePopup()}catch(e){}saveProject();toast('Saha notu silindi.');return true};window.aybOpenSahaNotForm=function(ll,ex){if(!project)return toast('Önce proje aç.');const old=$('#aybSahaNotModal');if(old)old.remove();const n=ex||{id:uid('SNOT'),lat:+ll.lat,lng:+ll.lng,tur:P[0][0],aciklama:P[0][1],objeNo:'',foto:'',created:new Date().toISOString()},v=!ex?L.marker([+ll.lat,+ll.lng],{icon:L.divIcon({className:'ayb-saha-note-marker',html:aybSahaNotIconHtml(n.id),iconSize:[24,24],iconAnchor:[12,12]}),interactive:false}).addTo(map):null;let foto=n.foto||'';const m=d.createElement('div');m.id='aybSahaNotModal';m.className='ayb-note-modal';m.innerHTML=`<div class="ayb-note-card"><div class="ayb-note-head">📝 SAHA NOTU<button data-x>×</button></div><div class="ayb-note-body"><div class="ayb-note-row"><label>Hazır Arıza / Not</label><select id="aybNotTur">${P.map(x=>'<option>'+x[0]+'</option>').join('')}</select></div><div class="ayb-note-row"><label>Direk / Obje No</label><input id="aybNotObje" value="${aybSahaNotEsc(n.objeNo||'')}"></div><div class="ayb-note-row"><label>Açıklama</label><textarea id="aybNotAcik">${aybSahaNotEsc(n.aciklama||'')}</textarea></div><div class="ayb-note-row"><label>Fotoğraf</label><div><input id="aybNotFoto" type="file" accept="image/*" capture="environment"><img id="aybNotFotoPrev" class="ayb-note-photo"></div></div></div><div class="ayb-note-foot">${ex?'<button id="aybNotSil" class="danger">Sil</button>':''}<button data-x>İptal</button><button id="aybNotKaydet" class="save">Kaydet</button></div></div>`;d.body.appendChild(m);const t=$('#aybNotTur',m),a=$('#aybNotAcik',m),pr=$('#aybNotFotoPrev',m);t.value=n.tur||P[0][0];if(foto){pr.src=foto;pr.style.display='block'}let auto=(P.find(x=>x[0]===t.value)||['',''])[1];t.onchange=()=>{const q=(P.find(x=>x[0]===t.value)||['',''])[1];if(!a.value.trim()||a.value===auto)a.value=q;auto=q};function close(){if(v)try{map.removeLayer(v)}catch(e){}m.remove()}$$('[data-x]',m).forEach(x=>x.onclick=close);$('#aybNotFoto',m).onchange=function(){const f=this.files&&this.files[0];if(f)aybSahaNotFotoKucult(f,x=>{foto=x||foto;if(foto){pr.src=foto;pr.style.display='block'}})};$('#aybNotKaydet',m).onclick=()=>{n.tur=t.value;n.objeNo=$('#aybNotObje',m).value.trim();n.aciklama=a.value.trim();n.foto=foto;n.updated=new Date().toISOString();const ar=aybSahaNotes(),i=ar.findIndex(x=>String(x.id)===String(n.id));if(i>=0)ar[i]=n;else ar.push(n);project.sahaNotes=ar;projects[project.id]=project;close();window.renderSahaNot(n);saveProject();try{setTool('sahanot',{repeat:true})}catch(e){}toast('Saha notu kaydedildi. NOT aracı açık.')};const z=$('#aybNotSil',m);if(z)z.onclick=()=>{if(v)try{map.removeLayer(v)}catch(e){}window.aybSahaNotSil(n.id)}};window.aybSahaNotGit=id=>{const n=aybSahaNotById(id);if(!n)return;map.setView([+n.lat,+n.lng],Math.max(map.getZoom(),19));const m=window.renderSahaNot(n);setTimeout(()=>m.openPopup(),120)};let bd=0,tt=setInterval(()=>{if(!bd&&typeof map!=='undefined'&&map){bd=1;map.on('zoomanim',e=>{const z=map.getZoomScale(e.zoom,map.getZoom());d.documentElement.style.setProperty('--ayb-note-inv',String(z?1/z:1))});map.on('zoomend',()=>d.documentElement.style.setProperty('--ayb-note-inv','1'))}if(bd)clearInterval(tt)},100);
})();</script>'''
